-- Command ids are `<namespace>.<area>.<verb>` (`.context/commands.md`):
-- core's and oxplow's own extensions' are `oxplow.*`. History is rewritten
-- to them, best effort and once (no compatibility with the old ids): the
-- id columns, and every whole JSON string naming an old id in the stored
-- calls, previews, inputs, resends and `command.*` / `effect.*` event
-- payloads. No event type equals a command id, so a quoted old id names a
-- command.
CREATE TEMP TABLE command_id_rename (old TEXT PRIMARY KEY, new TEXT NOT NULL);

UPDATE command_audit
   SET command = (SELECT new FROM command_id_rename WHERE old = command_audit.command)
 WHERE command IN (SELECT old FROM command_id_rename);
UPDATE command_proposal
   SET command = (SELECT new FROM command_id_rename WHERE old = command_proposal.command)
 WHERE command IN (SELECT old FROM command_id_rename);

